CREATE TABLE kv (
  k VARBINARY(256) PRIMARY KEY,
  v LONGBLOB NOT NULL,
  version BIGINT NOT NULL DEFAULT 1,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
    ON UPDATE CURRENT_TIMESTAMP,
  expires_at TIMESTAMP NULL,
  INDEX idx_expires (expires_at)
) ENGINE=InnoDB;
-- get: SELECT v, version FROM kv WHERE k = ?;
-- put: INSERT INTO kv(k,v,version) VALUES(?,?,1)
--   ON DUPLICATE KEY UPDATE v=VALUES(v), version=version+1;

classDiagram
  class Router {
    +put(key, value)
    +get(key, consistency)
    +route(key)
  }
  class Directory {
    +version int
    +getPhysical(virtualId)
    +moveRange()
  }
  class Shard {
    +primaryHost
    +standbyHost
    +replicaHosts
  }
  class KvRow {
    +key bytes
    +value bytes
    +version int
  }
  Router --> Directory
  Router --> Shard
  Shard --> KvRow

public class ShardedKvRouter {
  private static final int VIRTUAL_SHARDS = 4096;
  private volatile Directory dir; // polled every 1s, versioned
  private final Map<Integer, HikariPool> pools; // physShard -> pool
  private final Cache cache;

  private int vShard(byte[] key) {
    long h = XXH3.hash64(key); // stable, fast, uniform
    return (int) ((h & Long.MAX_VALUE) % VIRTUAL_SHARDS);
  }

  public byte[] get(byte[] key, boolean strongRead) throws Exception {
    byte[] hit = cache.get(key);
    if (hit != null) return hit;
    int phys = dir.getPhysical(vShard(key));
    String sql = "SELECT v, version FROM kv WHERE k=?";
    DataSource ds = strongRead ? pools.get(phys).primary()
                               : pools.get(phys).lagBoundedReplica();
    try (Connection c = ds.getConnection();
         PreparedStatement ps = c.prepareStatement(sql)) {
      ps.setBytes(1, key);
      ResultSet rs = ps.executeQuery();
      if (!rs.next()) return null;
      byte[] v = rs.getBytes(1);
      cache.put(key, v, 30);
      return v;
    }
  }

  public void put(byte[] key, byte[] val, long ttlSec) throws Exception {
    int phys = dir.getPhysical(vShard(key));
    String sql = "INSERT INTO kv(k,v,version,expires_at) VALUES(?,?,1,?) " +
      "ON DUPLICATE KEY UPDATE v=VALUES(v), version=version+1, expires_at=VALUES(expires_at)";
    try (Connection c = pools.get(phys).primary().getConnection();
         PreparedStatement ps = c.prepareStatement(sql)) {
      ps.setBytes(1, key); ps.setBytes(2, val);
      ps.setTimestamp(3, ttlSec > 0 ? expiresIn(ttlSec) : null);
      ps.executeUpdate(); // sync standby commit via semi-sync replication
    }
    cache.invalidate(key); // delete, never update: avoids version race
  }
}
